function initWorld(){let r=rng(973116);WORLD.buildings=[];WORLD.trees=[];WORLD.wrecks=[];WORLD.caches=[];WORLD.zombies=[];WORLD.npc=[];
  for(let x=90;x<W-130;x+=210)for(let y=100;y<H-130;y+=190){
    if(x>1360&&x<1560|| x>2120&&x<2240 || y>270&&y<425||y>800&&y<950||y>1260&&y<1400)continue;
    if(MISSIONS.some(m=>Math.hypot(m.x-(x+65),m.y-(y+55))<178))continue;
    if(r()<.83)WORLD.buildings.push({x:x+8,y:y+6,w:130+r()*42,h:102+r()*32,color:Math.floor(r()*4),label:r()<.08?'MERCADO':r()<.08?'DEPÓSITO':''});
  }
  for(let i=0;i<370;i++){let x=50+r()*(W-100),y=50+r()*(H-100);if(!isRoad(x,y)&&!blocked(x,y,23)&&!MISSIONS.some(m=>Math.hypot(m.x-x,m.y-y)<90))WORLD.trees.push({x,y,r:12+r()*19,shade:r()});}
  for(let i=0;i<110;i++){let x=80+r()*(W-160),y=80+r()*(H-160);if(isRoad(x,y)&&!MISSIONS.some(m=>Math.hypot(m.x-x,m.y-y)<95))WORLD.wrecks.push({x,y,rot:r()*6.2});}
  for(let i=0;i<95;i++){let x=50+r()*(W-100),y=50+r()*(H-100);if(!blocked(x,y,32)&&!MISSIONS.some(m=>distance(m,{x,y})<100))WORLD.caches.push({id:i,x,y,type:['food','water','medkit','ammo'][Math.floor(r()*4)],amount:1+Math.floor(r()*2)});}
  WORLD.npc=[{x:477,y:310,name:'Dra. Sofia',color:'#c9b0a1'},{x:855,y:579,name:'Nina',color:'#dcad75'},{x:1215,y:836,name:'Raul',color:'#8fb6ae'},{x:2680,y:690,name:'Helena',color:'#a5c6da'},{x:2995,y:1030,name:'Tomás',color:'#d1b88b'},{x:3050,y:1680,name:'Eva',color:'#8eb9e0'},{x:2730,y:2020,name:'Lia',color:'#a5aacd'},{x:3170,y:2175,name:'Íris',color:'#c4b4ce'},{x:2250,y:1860,name:'Bento',color:'#ddc38a'},{x:3060,y:1370,name:'Vítor',color:'#c5b8a9'},...EXT_BEATS.filter((m,i)=>i%2===0).map(m=>({x:m.x+24,y:m.y+24,name:m.speaker.split(' / ')[0],color:'#e0ba86'}))];
}
function isRoad(x,y){return [340,840,1340,1930,2510,3090].some(v=>Math.abs(y-v)<62)||[320,920,1520,2180,2830,3230,3830,4430,5030].some(v=>Math.abs(x-v)<69)}
function blocked(x,y,r=13){if(x<25+r||x>W-25-r||y<25+r||y>H-25-r)return true;return WORLD.buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
function moveEntity(entity,dx,dy,r=13){const barrier=(x,y)=>WORLD.zombies.includes(entity)&&s.v11.barricades.some(b=>b.life>0&&Math.hypot(b.x-x,b.y-y)<38);if(!blocked(entity.x+dx,entity.y,r)&&!barrier(entity.x+dx,entity.y))entity.x+=dx;if(!blocked(entity.x,entity.y+dy,r)&&!barrier(entity.x,entity.y+dy))entity.y+=dy}
