  g.fillStyle='#515b51';for(const y of [340,840,1340,1930,2510,3090])g.fillRect(0,y-57,W,114);for(const x of [320,920,1520,2180,2830,3230,3830,4430,5030])g.fillRect(x-64,0,128,H);
