function visible(p,r=0){return p.x+r>camX&&p.x-r<camX+cw&&p.y+r>camY&&p.y-r<camY+ch}
function drawPerson(x,y,color,infected=false,name='',player=false){let g=cx;g.fillStyle='#0d160e80';g.beginPath();g.ellipse(x+3,y+15,14,7,0,0,7);g.fill();g.fillStyle=infected?'#343b30':color;g.beginPath();g.arc(x,y,11,0,7);g.fill();g.fillStyle=infected?'#bf4e3f':'#273c34';g.beginPath();g.arc(x,y-5,5,0,7);g.fill();g.fillStyle=player?'#dfeeb0':'#d0d8c2';g.fillRect(x-4,y+4,8,6);if(name){g.font='bold 10px sans-serif';g.fillStyle=player?'#e4f4bb':'#e2e4d5';g.textAlign='center';g.fillText(name,x,y-19);g.textAlign='left'}if(player){g.strokeStyle='#e4f0a2b8';g.lineWidth=2;g.beginPath();g.arc(x,y,17,0,7);g.stroke()}}
function setDifficulty(mode){difficulty=mode==='survival'?'survival':'story';localStorage.setItem('ut-v6-difficulty',difficulty);showIntro()}
function startNew(show=true){if(coop)leaveRoom();s=base();WORLD.others={};WORLD.zombies=[];save();updateHUD();if(show)showIntro();else beginCampaign()}
function tick(dt){if(paused||s.ended)return;if(v11TickInterior(dt))return;const vel=180*(dt/1000)*(v11IsSneaking()?.52:1);let mx=0,my=0;if(keys.w||keys.arrowup)my--;if(keys.s||keys.arrowdown)my++;if(keys.a||keys.arrowleft)mx--;if(keys.d||keys.arrowright)mx++;if(mx||my){let n=Math.hypot(mx,my),dx=mx/n*vel,dy=my/n*vel;let prevX=s.x,prevY=s.y;moveEntity(s,dx,dy);if(s.quest<5&&s.x>1435){s.x=1435;if(prevX<1435&&now%1000<20)toast('O setor leste será liberado no segundo capítulo.',true)}let traveled=Math.hypot(s.x-prevX,s.y-prevY);s.steps+=traveled;s.time+=traveled*.008;s.hunger=clamp(s.hunger-traveled*(difficulty==='story'?.0017:.0034),0,100);s.thirst=clamp(s.thirst-traveled*(difficulty==='story'?.002:.0041),0,100);}
 if(s.hunger<=0||s.thirst<=0)s.health=clamp(s.health-dt*.0015,0,100);if(s.infection>60)s.health=clamp(s.health-dt*.0008,0,100);
 zombieTimer+=dt;spawnTicker+=dt;
 if(spawnTicker>1400){spawnTicker=0;spawnZombies();}
 if(zombieTimer>42){const dd=zombieTimer/1000;zombieTimer=0;for(const z of WORLD.zombies){let d=distance(z,s);let aggro=((s.quest>4?225:175)*(difficulty==='story'?.72:1)+(s.flags.loudSignal?85:0))*(v11IsSneaking()?.55:1)+s.v11.noise;if(d<aggro || z.target&&now<z.targetUntil){const goal=z.target&&now<z.targetUntil?z.target:s;z.dir=Math.atan2(goal.y-z.y,goal.x-z.x);moveEntity(z,Math.cos(z.dir)*dd*z.speed*(z.kind==='runner'?1.35:z.kind==='brute'?.72:1),Math.sin(z.dir)*dd*z.speed*(z.kind==='runner'?1.35:z.kind==='brute'?.72:1),10)}else{if(random()<.013)z.dir=random()*6.283;moveEntity(z,Math.cos(z.dir)*dd*z.speed*.13,Math.sin(z.dir)*dd*z.speed*.13,10)}if(d<(z.kind==='brute'?31:24)&&now-z.lastHit>1250){z.lastHit=now;if(now<s.v11.rollingUntil)continue;s.health=clamp(s.health-(difficulty==='story'?3:(s.quest>4?9:7))*(z.kind==='brute'?1.7:1),0,100);if(random()<(difficulty==='story'?.04:.12))s.infection=clamp(s.infection+4,0,100);$('damage-flash').style.opacity='.7';setTimeout(()=>$('damage-flash').style.opacity='0',190);beep(90,.2,'sawtooth',.12);toast('Um infectado atingiu você!',true);}}WORLD.zombies=WORLD.zombies.filter(z=>distance(z,s)<820);}
 for(const p of WORLD.particles){p.x+=p.vx*dt/1000;p.y+=p.vy*dt/1000;p.life-=dt/350;}WORLD.particles=WORLD.particles.filter(p=>p.life>0);
 v11Tick(dt);if(s.steps>3000)unlock('explorador');if(s.health<=0||s.infection>=100)die();hudTicker+=dt;if(hudTicker>210){hudTicker=0;updateHUD()}
 if(now-lastAutosave>10000){lastAutosave=now;save()}if(coop&&ws&&ws.readyState===1&&now-lastPositionSend>160){lastPositionSend=now;sendWs({type:'position',x:Math.round(s.x),y:Math.round(s.y),health:Math.round(s.health)})}
}
function spawnZombies(){if(WORLD.zombies.length>=(difficulty==='story'?12:MAX_ZOMBIES))return;let count=(difficulty==='story'?1:2)+(s.quest>4&&difficulty==='survival'?1:0);for(let i=0;i<count;i++){let angle=random()*6.283,r=310+random()*270,x=clamp(s.x+Math.cos(angle)*r,30,W-30),y=clamp(s.y+Math.sin(angle)*r,30,H-30);if((s.quest<5&&x>1440)||blocked(x,y,15))continue;WORLD.zombies.push({x,y,hp:2+(s.quest>4?1:0),speed:30+random()*24,dir:random()*6.28,lastHit:0,kind:random()<.17?'brute':random()<.32?'runner':'walker'})}}
function particles(x,y,color,count=7){for(let i=0;i<count;i++)WORLD.particles.push({x,y,vx:(random()-.5)*105,vy:(random()-.5)*105,life:1,size:random()*3,color})}
function strike(shoot=false){if(paused||s.ended)return;if(shoot&&s.ammo<1){toast('Munição esgotada.',true);return}let targets=WORLD.zombies.map(z=>({z,d:distance(s,z)})).filter(t=>t.d<(shoot?295:58)).sort((a,b)=>a.d-b.d);if(shoot){s.v11.noise=200;s.ammo--;beep(130,.12,'sawtooth',.1);beep(55,.2,'triangle',.08)}else beep(210,.07,'triangle');if(targets.length){let z=targets[0].z;z.hp-=shoot?2:(v11IsSneaking()?2:1);particles(z.x,z.y,'#9a4940',9);if(z.hp<=0){WORLD.zombies=WORLD.zombies.filter(t=>t!==z);s.kills++;s.xp+=10;v11Killed(z);toast('Infectado eliminado  +10 XP');if(s.kills>=15)unlock('cacador')}}else if(shoot)toast('Tiro disparado — nenhum alvo no alcance.');checkLevel();updateHUD();save()}
function nearInteraction(){let v=v11Near();if(v)return{kind:'v11',obj:v,d:0};let m=MISSIONS[s.quest];if(m&&distance(s,m)<92)return{kind:'quest',obj:m,d:distance(s,m)};let nearest=WORLD.caches.filter(c=>!s.loot.includes(c.id)).map(obj=>({kind:'cache',obj,d:distance(s,obj)})).sort((a,b)=>a.d-b.d)[0];if(nearest&&nearest.d<52)return nearest;return null}
function interact(){if(paused||s.ended)return;if(v11Interact())return;const n=nearInteraction();if(!n){toast('Aproxime-se de um ponto de interesse ou caixa de suprimentos.',true);return}if(n.kind==='quest'){showQuest();return}let c=n.obj;s[c.type]+=c.amount;s.loot.push(c.id);s.xp+=5;toast(`Encontrou ${c.amount}x ${resourceName(c.type)}!`);log(`Suprimentos encontrados: ${resourceName(c.type)} +${c.amount}.`);beep(700,.12);checkLevel();updateHUD();save()}
const resourceName=k=>({food:'comida',water:'água',medkit:'kit médico',ammo:'munição'})[k]||k;
function useItem(item){if(paused||s.ended||coop&&overlayMode==='vote')return;if(item==='ammo'){toast('Munição: pressione F ou o botão TIRO para atirar.');return}if(s[item]<1){toast(`Sem ${resourceName(item)} disponível.`,true);return}if(item==='food'){s.food--;s.hunger=clamp(s.hunger+42,0,100)}if(item==='water'){s.water--;s.thirst=clamp(s.thirst+49,0,100)}if(item==='medkit'){s.medkit--;s.health=clamp(s.health+38,0,100);s.infection=clamp(s.infection-12,0,100)}toast(`${resourceName(item).toUpperCase()} utilizado.`);beep(650,.13);save();updateHUD()}
function canChoose(o){if(o.requiresFlagsAll&&!o.requiresFlagsAll.every(f=>s.flags[f]))return false;if(o.requiresFlag&&!s.flags[o.requiresFlag])return false;if(o.forbidsFlag&&s.flags[o.forbidsFlag])return false;if(o.requires&&Object.entries(o.requires).some(([k,v])=>s[k]<v))return false;if(o.requiresFlagAny&&!o.requiresFlagAny.some(f=>s.flags[f]))return false;return true}
function applyChoice(q,opt,withUi=true){const m=MISSIONS[q];if(!m||s.quest!==q)return;const o=m.options.find(o=>o.id===opt);if(!o)return;const e=o.effects||{};for(const [k,v] of Object.entries(e))if(['health','hunger','thirst','infection','food','water','medkit','ammo','xp'].includes(k))s[k]=k==='xp'?s[k]+v:clamp(s[k]+v,0,k==='health'||k==='hunger'||k==='thirst'||k==='infection'?100:999);
 if(e.trust)for(const [k,v]of Object.entries(e.trust))s.trust[k]=clamp(s.trust[k]+v,0,100);if(e.flag)s.flags[e.flag]=true;const passage=o.aftermath||'A escolha altera a próxima etapa da viagem.';s.recollections.push({quest:q,chapter:m.chapter,title:m.title,choice:o.title,aftermath:passage});s.decisions.push({quest:q,choice:opt});s.quest++;s.time+=35;v11AfterChoice(q,opt);if(withUi)log(`${m.region}: ${o.title}.`);else s.logs.unshift(`${m.region}: ${o.title}.`);if(s.quest===5){unlock('segundo-dia');if(withUi){toast('CAPÍTULO 2 DESBLOQUEADO — SETOR LESTE');beep(750,.25)}}if(s.quest===10)unlock('terceiro-ato');if(s.quest===22)unlock('resistencia');if(s.quest>=78)unlock('quinze-capitulos');if(s.flags.oliviaBond||s.flags.oliviaSlow)unlock('familia');if(s.flags.manifestPublic&&s.flags.farewellBridge)unlock('rede');if(s.flags.recordsAnonymized||s.flags.finalEvidencePublic)unlock('testemunhos');if(s.flags.festivalHope||s.flags.schoolFree)unlock('infancia');if(s.flags.namesRemembered)unlock('memoria');if(s.flags.danielAlive)unlock('encontro');if(['archiveReleased','archiveProtected','evidenceSaved','vitorFiles','medicalRecords','pumpEvidence'].some(k=>s.flags[k]))unlock('testemunha');if(s.quest===1)unlock('primeiros-passos');if(s.flags.ninaSafe)unlock('resgate');if(s.flags.raulAlly)unlock('alianca');if(s.flags.shelterDefended||s.flags.shelterFed)unlock('protetor');if(s.quest>=MISSIONS.length){finish(withUi);return}checkLevel();updateHUD();save();if(withUi){beep(570,.15);showAftermath(m,o)}}
function checkLevel(){let newLevel=1+Math.floor(s.xp/100);if(newLevel>s.level){s.level=newLevel;toast(`NOVO NÍVEL: ${newLevel}`);s.health=clamp(s.health+15,0,100);beep(820,.22)}}
function unlock(id){if(!s.achievements.includes(id)){s.achievements.push(id);if(!paused)toast('CONQUISTA: '+(BADGES.find(a=>a[0]===id)?.[1]||id));}}
function die(){if(s.ended)return;s.ended=true;s.endingId='collapse';s.ending='PORTO CINZA COBROU UM PREÇO — Clara perdeu a vida antes de concluir a transmissão. Nem todas as histórias chegam ao final, mas as escolhas permanecem no diário.';save();showEnding(false)}
function finish(withUi=true){
 s.ended=true;unlock('sobrevivente');unlock('sete-capitulos');unlock('quinze-capitulos');const f=s.flags;
 const care=['trainFamilies','manifestPublic','aliceReunited','samuelSheltered','kitchenFree','tunnelRescue','trialVoluntary','samuelConsent','oliviaBond','namesGuarded','schoolFree','siegeCorridor','newCouncil','infectedRights','farewellBridge'].filter(k=>f[k]).length;
 const truth=['evidenceSaved','fullTruth','recordsAnonymized','maraWitness','caioTrial','archiveProofs','archiveNames','signalForgery','vitorVideoKept','vitorVideoTrial','finalEvidencePublic','finalEvidenceCourt','radioUncut'].filter(k=>f[k]).length;
 const family=['aliceReunited','danielReconciled','oliviaBond','juliaTrust','doraLetterShared','oliviaFuture','doraLegacy','rememberChildVoice','rememberGriefShared'].filter(k=>f[k]).length;
 const harm=['manifestSecret','aliceCut','samuelForced','doseFavoritism','juliaSeparated','siegePatients','schoolControl','newAutocracy','infectedForever','finalEvidenceSold','farewellClosed','oliviaTaken'].filter(k=>f[k]).length;
 let outcome;
 if(f.v6EndingTogether){
   if(family>=5&&truth>=7&&care>=9)outcome=['dawn-chorus','O CORO DO AMANHÃ','A cidade decide por voto aberto coordenar a travessia, preservar provas e manter a escola. Clara aprende que ninguém precisa carregar a história sozinho.'];
   else if(care>=7&&f.newCouncil)outcome=['shared-morning','A MANHÃ DE TODOS','A assembleia assume a transmissão e organiza socorro com mandatos temporários. Não há promessa de unanimidade; há lugar para discordar.'];
   else outcome=['open-mic','O MICROFONE ABERTO','Pessoas com diferentes medos contam o que perderam e o que querem reconstruir. O sinal permanece aberto depois que Clara se cala.'];
 } else if(f.v6EndingSea){
   unlock('mar-aberto');
   if(care>=9&&f.newCouncil&&f.farewellBridge)outcome=['fleet','A FROTA DOS NOMES','Navios e ônibus partem em horários combinados com os bairros. Não levam só pessoas; levam arquivos, escolas e a promessa de resposta.'];
   else if(family>=5&&f.oliviaTravel)outcome=['family-sea','UM LAR ALÉM DA MARÉ','Clara atravessa com Daniel, Júlia e Olívia. A menina desenha uma casa com portas nas duas margens.'];
   else if(f.manifestPublic&&f.borderRotations)outcome=['many-ports','A COSTA DOS ABRIGOS','O cais se torna uma rede de portos pequenos. A viagem leva semanas, e nenhum navio precisa escolher tudo sozinho.'];
   else if(f.manifestSecret||f.borderInnerCircle)outcome=['boat-elite','O CONVÉS DOS ESCOLHIDOS','O navio chega seguro, mas os passageiros descobrem quantas pessoas foram apagadas da lista para que partissem.'];
   else if(f.samuelConsent&&f.infectedRights)outcome=['sea-hospital','UM HOSPITAL EM MOVIMENTO','O Aurora vira enfermaria e escola flutuante. Os infectados conscientes decidem se querem embarcar.'];
   else if(care>=6)outcome=['caravan-sea','A CARAVANA DAS DUAS MARGENS','As famílias alcançam o mar por caminhos diferentes e descobrem que uma comunidade não precisa de uma única casa.'];
   else outcome=['sea-uncertain','O MAR NÃO APAGA O PASSADO','A travessia começa sob uma tempestade. Alguns sobrevivem e outros ficam esperando a próxima maré, com uma frequência aberta.'];
 } else if(f.v6EndingTruth){
   if(truth>=9&&f.finalEvidencePublic&&f.maraWitness)outcome=['trial-world','O DIA EM QUE O MUNDO ESCUTOU','A investigação alcança cidades distantes. Mara depõe contra o próprio pai; o testemunho não devolve os mortos, mas impede que sejam negados.'];
   else if(f.recordsAnonymized&&f.finalEvidenceCourt&&f.caioTrial)outcome=['justice-care','JUSTIÇA COM NOMES PROTEGIDOS','Uma comissão independente preserva provas e testemunhas. O julgamento começa sem repetir a violência da contenção.'];
   else if(f.radioUncut&&f.signalForgery)outcome=['clear-signal','A FREQUÊNCIA SEM CORTES','Cidadãos aprendem a reconhecer falsificações e guardar gravações originais. O poder não controla mais sozinho o que foi ouvido.'];
   else if(f.finalEvidenceSold||f.recordsBlackmail)outcome=['truth-purchased','O PREÇO DA VERDADE','O mundo ouve a história, mas as provas decisivas foram negociadas. Clara sobrevive e precisa admitir a parte que escondeu.'];
   else if(f.vitorVideoKept&&f.danielReconciled)outcome=['siblings-truth','AS DUAS VOZES DOS MENDES','Clara e Daniel contam suas versões, inclusive o que fizeram de errado. Olívia ouve a história da família sem precisar transformá-la em lenda.'];
   else if(truth>=5)outcome=['witness-network','A REDE DE TESTEMUNHAS','Provas e depoimentos atravessam as fronteiras. Cada estação preserva uma cópia para que o silêncio não volte a ser uma ordem.'];
   else outcome=['last-record','UM TESTEMUNHO INCOMPLETO','Clara transmite o que sabe e admite o que não consegue provar. Sua honestidade não encerra o caso, mas evita outra mentira.'];
 } else {
   unlock('cidade-livre');
   if(f.newCouncil&&f.schoolFree&&f.infectedRights&&care>=8)outcome=['year-one','PORTO CINZA, ANO UM','O primeiro documento da cidade não é uma ordem de guerra, mas uma carta de direitos. A escola abre no mesmo dia que o hospital.'];
   else if(f.oliviaFuture&&f.doraLegacy&&family>=4)outcome=['house-open','A CASA DAS PORTAS ABERTAS','Olívia escolhe uma rua para plantar árvores; Clara e Daniel aprendem que família é uma responsabilidade partilhada.'];
   else if(f.newAutocracy||f.farewellClosed)outcome=['fortress','A FORTALEZA DAS VOZES BAIXAS','A cidade resiste atrás de muros, mas os sobreviventes descobrem que o preço da ordem é pedir licença para lembrar.'];
   else if(f.trialVoluntary&&f.infectedCenters&&f.schoolCivic)outcome=['living-lab','A CIDADE QUE APRENDE','Escolas, clínicas e laboratórios trabalham com regras públicas, voluntários e o direito de mudar de ideia.'];
   else if(f.kitchenFree&&f.desertersWitness&&f.newCouncil)outcome=['second-neighbors','SEGUNDOS VIZINHOS','Antigos inimigos dividem uma mesa. Ninguém esquece o que fizeram, mas todos sabem como participar de um recomeço.'];
   else if(care>=5&&harm<=2)outcome=['open-city','AS PORTAS DE PORTO CINZA','Há ruas ainda perigosas e casas vazias. O conselho mantém as portas abertas e faz da solidariedade uma tarefa diária.'];
   else outcome=['city-fragile','A CIDADE QUE AINDA RESPIRA','O gerador volta, a escola tenta reabrir e famílias discutem o futuro. Não é um final feliz pronto: é uma chance que precisa ser cuidada.'];
 }
 outcome=v11SpecialEnding(outcome);const [id,title,detail]=outcome;s.endingId=id;s.ending=title+' — '+detail;
 if(f.finalEvidencePublic||f.finalEvidenceCourt)unlock('sem-silencio');
 log('Desfecho '+title+': '+detail);save();if(withUi)showEnding(true)
}
function epilogue(){const f=s.flags;
 const fate=[
  ['Daniel',f.danielAlive?'Reencontrado, ajuda Clara a reconstruir o registro das transmissões.':f.danielIsolated?'Permanece isolado, vivo, aguardando a próxima avaliação.':f.danielLeft?'Sua porta continua fechada; Clara jamais saberá o que houve depois.':'Seu rastro sobrevive nos registros que Clara conseguiu preservar.'],
  ['Sofia',s.trust.sofia>=65?'Conduz a equipe de saúde e assume publicamente seus erros.':s.trust.sofia<30?'Afasta-se do grupo, incapaz de voltar a confiar em Clara.':'Segue atendendo sobreviventes apesar do futuro incerto.'],
  ['Nina',f.ninaLeft?'Seu destino não foi confirmado após o chamado da farmácia.':f.ninaMotherClue?'Continua a busca pela mãe no Círculo Norte.':s.trust.nina>=55?'Mantém o contato entre as comunidades pelos rádios.':'Segue para uma região desconhecida levando o próprio transmissor.'],
  ['Raul',f.raulExiled?'Parte sozinho, com a fotografia da família e suas ferramentas.':s.trust.raul>=55?'Coordena reparos dos sistemas que mantêm os abrigos vivos.':'Sobrevive na oficina, distante das decisões do grupo.'],
  ['Helena',f.bridgeOpen||f.siegeEvac?'Rompe com antigas ordens e ajuda a proteger civis.':'Permanece guardando uma estrada cujo destino ainda está em disputa.'],
  ['Íris',f.cureEthical?'Abre os resultados de suas pesquisas e acompanha os pacientes que aceitaram o tratamento.':f.cureForced?'Carrega o peso das reações adversas que não foram explicadas.':'Continua procurando uma alternativa responsável ao tratamento experimental.'],
  ['Lia',f.signalBurned?'Escuta a frequência vazia e começa a registrar a história que não foi ao ar.':'Mantém um arquivo com as mensagens recebidas e os nomes de quem pediu ajuda.']
 ];
 fate.push(
 ['Olívia', f.oliviaFuture?'Começa a estudar numa escola comunitária, onde sua primeira redação fala de uma casa com portas abertas.':f.oliviaTaken||f.oliviaEvacuatedAlone?'Viaja afastada de pessoas que conhece. Sua história ainda exige reparação e reencontro.':'Continua desenhando o futuro com Júlia, sem esquecer as perguntas que tem para Daniel.'],
 ['Júlia',f.juliaTrust?'Aceita reaproximar-se da família Mendes, desde que Olívia seja ouvida em todas as decisões.':f.juliaSeparated?'Procura a filha por cada frequência disponível.':'Protege a autonomia da filha e a própria vida diante dos novos caminhos.'],
 ['Alice',f.aliceReunited?'Conversa com Nina após anos de silêncio, sem exigir perdão imediato.':f.aliceCut?'Permanece em uma estação distante e tenta reabrir o contato.':'Divulga as gravações que a Helix tentou silenciar.'],
 ['Samuel',f.infectedRights?'Ajuda a escrever os direitos dos infectados conscientes e volta a aprender violão.':f.samuelForced||f.samuelTransferred?'Seu destino depende de uma contenção que nunca consultou a própria vontade.':'Recebe acompanhamento e preserva a possibilidade de escolher seu tratamento.'],
 ['Bento',f.namesGuarded||f.archiveConsent?'Mantém um arquivo de nomes com acesso consentido e espaços para histórias futuras.':f.namesMilitia?'Recusa-se a escrever enquanto o caderno estiver nas mãos da milícia.':'Encontra palavras para registrar o que testemunhou.'],
 ['Mara',f.maraWitness?'Testemunha sobre as decisões do pai e assume responsabilidade por seu próprio projeto.':f.maraDeal?'Carrega documentos que já não consegue recuperar.':'Ajuda a decifrar a arquitetura da Helix.'],
 ['Joana',f.trialVoluntary?'Continua a pesquisa com consentimento informado e dados compartilhados.':f.doseFavoritism?'Tenta reparar a confiança quebrada pela seleção de pacientes.':'Trabalha em uma clínica aberta à comunidade.'],
 ['Rosa',f.newCouncil?'Organiza assembleias, refeitórios e mecanismos para substituir qualquer liderança.':f.newAutocracy?'Resiste ao controle de uma nova autoridade dentro das muralhas.':'Mantém a cozinha aberta e procura quem ainda não voltou.'],
 ['Levi',f.manifestPublic?'Garante que a lista de passageiros possa ser consultada e contestada.':f.manifestSecret?'Carrega o peso dos lugares decididos em segredo.':'Mantém a rota do Aurora em contato com Porto Cinza.'],
 ['Cecília',f.schoolFree?'Ensina as crianças a perguntar por quê antes de responder.':f.festivalCancelled?'Mantém uma caixa de giz guardada para um dia menos perigoso.':'Protege a escola em meio ao que restou da cidade.'],
 ['Estela',f.recordsAnonymized?'Conserva provas com nomes protegidos e históricos verificáveis.':f.recordsBlackmail?'Vê seu trabalho de arquivista ser usado como ameaça.':'Organiza um arquivo que ninguém possa apagar sozinho.']
 );
 return fate.map(([who,what])=>`<div class="epilogue-person"><b>${escapeHtml(who)}</b><span>${escapeHtml(what)}</span></div>`).join('');
}
function updateHUD(){const next=MISSIONS[s.quest];$('quest-index').textContent=next?`MISSÃO ${String(s.quest+1).padStart(2,'0')} / ${MISSIONS.length}`:'CAMPANHA CONCLUÍDA';$('quest-title').textContent=next?.title||'Você chegou ao fim';$('quest-hint').textContent=next?.hint||s.ending;$('quest-distance').textContent=next?`${Math.round(distance(s,next))} m até o objetivo`:'CAMPANHA FINALIZADA';$('region').textContent=next?.region||'PORTO CINZA';$('chapter-label').textContent=`CAP. ${next?.chapter||15}`;$('rank').textContent=`NÍVEL ${String(s.level).padStart(2,'0')} · ${s.xp} XP`;
 for(const [stat,max] of [['health',100],['hunger',100],['thirst',100],['infection',100]]){$(stat+'-value').textContent=`${Math.round(s[stat])}${stat==='health'?'/100':'%'}`;$(stat+'-bar').style.width=clamp(s[stat]/max*100,0,100)+'%'}for(const k of ['food','water','medkit','ammo'])$(k+'-value').textContent=s[k];$('clock').textContent=`DIA ${String(1+Math.floor(s.time/1440)).padStart(2,'0')} · ${String(Math.floor(s.time%1440/60)).padStart(2,'0')}:${String(Math.floor(s.time%60)).padStart(2,'0')}`;$('coordinates').textContent=`X: ${Math.round(s.x)} Y: ${Math.round(s.y)}`;$('achievement-count').textContent=`${s.achievements.length}/${BADGES.length} CONQUISTAS`;renderRelations();const n=nearInteraction();$('interaction-hint').classList.toggle('hidden',!n||paused);if(n)$('interaction-hint').textContent=n.kind==='quest'?'[ E ] INICIAR MISSÃO':n.kind==='v11'?'[ E ] '+(n.obj.label||'INTERAGIR'):'[ E ] COLETAR RECURSO';v11HUD();}
function renderRelations(){$('relations').replaceChildren();for(const [k,name] of [['nina','Nina'],['sofia','Sofia'],['raul','Raul'],['helena','Helena'],['tomas','Tomás'],['eva','Eva'],['lia','Lia'],['iris','Íris'],['daniel','Daniel'],['olivia','Olívia'],['rosa','Rosa'],['joana','Joana'],['alice','Alice'],['mara','Mara'],['levi','Levi']]){let row=document.createElement('div');row.className='relation';row.innerHTML=`<span class="name">${name}</span><span class="track"><i style="width:${s.trust[k]}%"></i></span><span class="score">${s.trust[k]}</span>`;$('relations').append(row)}}
function renderLog(){if(!$('log'))return;$('log').replaceChildren();for(const msg of s.logs.slice(0,7)){let d=document.createElement('div');d.className='log-item';d.textContent=msg;$('log').append(d)}}
function show(html,mode='menu'){overlayMode=mode;modalOpen=true;paused=true;$('overlay').classList.remove('hidden');$('modal').innerHTML=html;$('modal').scrollTop=0;}
function resume(){if(s.ended){showEnding(true);return}overlayMode='';modalOpen=false;paused=false;$('overlay').classList.add('hidden');canvas.focus();}
function showIntro(){const current=MISSIONS[s.quest];show(`<div class="eyebrow">SAGA COMPLETA / ${STORY_CHAPTERS.length} CAPÍTULOS</div><h1>QUANDO O MUNDO CALOU,<br><span class="ending">VOCÊ AINDA OUVIU.</span></h1><p class="lead">Clara procura o irmão desaparecido enquanto uma cidade inteira tenta sobreviver ao apagamento. Cada escolha pode salvar alguém — ou deixar cicatrizes que reaparecem muitos capítulos depois.</p><div class="hero-divider"></div><div class="info">MUNDO ABERTO VIVO · ${MISSIONS.length} MISSÕES COM OBJETIVOS · ${STORY_CAST.length} PERSONAGENS · FLASHBACKS EXPLORÁVEIS · INTERIORES · COOPERATIVO EXPERIMENTAL</div><p class="note">${current?`Campanha salva: capítulo ${current.chapter}, missão ${s.quest+1}.`:'Campanha concluída. Você pode iniciar outra história para descobrir novos desfechos.'}</p><div class="choices"><button class="primary" data-action="continue">${s.decisions.length||s.steps>0?'CONTINUAR CAMPANHA':'INICIAR HISTÓRIA'}</button><button class="secondary" data-action="new">NOVA CAMPANHA</button><button class="secondary" data-action="cast">CONHECER PERSONAGENS</button><button class="secondary" data-action="craft">FABRICAR EQUIPAMENTOS</button><button class="secondary" data-action="team">COMPANHEIROS</button><button class="secondary" data-action="help">CONTROLES</button></div><div class="difficulty-select"><strong>RITMO DA CAMPANHA</strong><p>Modo História: menos zumbis e maior foco nos personagens. Sobrevivência: perigos e consumo de recursos mais intensos.</p><div class="row"><button class="${difficulty==='story'?'primary':'secondary'}" data-action="mode-story">HISTÓRIA ${difficulty==='story'?'✓':''}</button><button class="${difficulty==='survival'?'primary':'secondary'}" data-action="mode-survival">SOBREVIVÊNCIA ${difficulty==='survival'?'✓':''}</button></div></div><p class="note">O modo solo salva localmente; a Cloudflare com D1 permite conta e sincronização entre dispositivos.</p>`,'intro')}
