function v11Safe(x,y,avoid=0){const tries=[[0,0],[35,0],[-35,0],[0,35],[0,-35],[55,55],[-55,-55],[85,0],[-85,0],[0,85],[0,-85],[135,0],[0,135],[-140,0]];for(const [dx,dy] of tries){const a={x:clamp(x+dx,48,W-48),y:clamp(y+dy,48,H-48)};if(!blocked(a.x,a.y,avoid||15))return a}return {x:clamp(x,48,W-48),y:clamp(y,48,H-48)};}
function v11InteriorDoor(loc){if(WORLD.v11Doors?.[loc.id])return WORLD.v11Doors[loc.id];const m=MISSIONS[loc.quest];return m?v11Safe(m.x+112,m.y+55,13):{x:330,y:410};}
function v11TaskStyle(q){const title=(MISSIONS[q]?.title||'').toLowerCase();if(/sinal|rádio|transmiss|antena|torre|rede|frequência/.test(title))return V11_TASKS[5];if(/hospital|escola|crian|refúgio|salvar|resgat|família/.test(title))return V11_TASKS[1];if(/arquiv|prova|verdade|laborat|registro|memória/.test(title))return V11_TASKS[0];if(/bloqueio|guerra|ataque|defesa|cerco/.test(title))return V11_TASKS[2];return V11_TASKS[q%V11_TASKS.length];}
function v11Target(a){const m=MISSIONS[a.q];if(!m)return null;const offs=a.phase?[-125,96]:[135,-98];if(a.kind==='defend'||a.kind==='purge')return v11Safe(m.x,m.y,12);return v11Safe(m.x+offs[0],m.y+offs[1],12);}
