 if(a.kind==='defend'&&a.phase===0){a.phase=1;a.timer=0;v11SpawnMissionThreat(4);toast('DEFENDA A POSIÇÃO POR 14 SEGUNDOS');beep(140,.3,'sawtooth');save();return true}
