function v11Companions(){const pool=Object.entries(V11_COMPANIONS).map(([id,v])=>({id,...v,locked:(id==='nina'&&s.flags.ninaLeft)||(id==='raul'&&s.flags.raulEnemy)||s.trust[id]<45}));show(`<div class="eyebrow">EQUIPE / SOBREVIVENTES</div><h2>COMPANHEIROS ATIVOS</h2><p>Um aliado pode acompanhar Clara, ajudar contra infectados e se ferir durante os confrontos. A confiança e suas decisões determinam quem aceita a viagem.</p><div class="info">Aliado: ${s.v11.companion?escapeHtml(V11_COMPANIONS[s.v11.companion].name):'NENHUM'} · Condição: ${s.v11.companionHealth}%</div><div class="choices">${pool.map(p=>`<button class="choice" data-action="v11-comp-${p.id}" ${p.locked?'disabled':''}><span>${escapeHtml(p.name)}${p.locked?' · INDISPONÍVEL':''}</span><small>Confiança: ${s.trust[p.id]||0}%</small></button>`).join('')}<button class="secondary" data-action="v11-comp-off">SEGUIR SOZINHA</button>${s.v11.companionHealth<100?'<button class="secondary" data-action="v11-heal">TRATAR ALIADO · 1 KIT MÉDICO</button>':''}</div><button class="secondary" data-action="back">FECHAR</button>`,'team')}
