function v11CraftMenu(){show(`<div class="eyebrow">SOBREVIVÊNCIA / FABRICAÇÃO</div><h2>BANCADA DE CAMPO</h2><p>Recolha peças e tecido em caixas e interiores. Produza equipamentos para explorar e enfrentar hordas.</p><div class="info">Peças: <b>${s.v11.scrap}</b> · Tecido: <b>${s.v11.cloth}</b> · Curativos: <b>${s.v11.bandages}</b> · Iscas: <b>${s.v11.decoys}</b> · Barricadas: <b>${s.v11.barricadesReady||0}</b></div><div class="choices"><button class="choice" data-action="v11-craft-bandage"><span>CURATIVO · 2 TECIDOS</span><small>Recupera 24 de vida, tecla H.</small></button><button class="choice" data-action="v11-craft-decoy"><span>ISCA SONORA · 2 PEÇAS</span><small>Distraia zumbis, tecla R.</small></button><button class="choice" data-action="v11-craft-barricade"><span>BARRICADA · 3 PEÇAS</span><small>Instale no mapa, tecla V.</small></button><button class="choice" data-action="v11-craft-purifier"><span>FILTRO DE ÁGUA · 2 PEÇAS</span><small>Encontre mais água (+3 unidades).</small></button></div><button class="secondary" data-action="back">VOLTAR</button>`,'craft')}
